function uploadShopList(n=null,t=null){$("#shopList").load("/ShopAction/ShopList",{shopId:n},(i,r,u)=>{if(r=="error"){console.error("/ShopAction/ShopList error: "+u.status+": "+u.statusText);console.trace(i);return}if(n==null){const n=$("a.shop_item");if(n.length==0)return;window.location.href=n.first().attr("href")}else setShopItemsPreventClick(),t!=null&&n!=0&&t(n)})}function loadShop(n){const t=`/ShopAction/${n}`;postData(t,null,n=>{$("#shopDiv").html(n)})}function setShopItemsPreventClick(){$(".shop_item").on("click",onShopItemChangePrevent)}function onShopItemChangePrevent(n){onItemChangePrevent(n,"/ShopAction/IsChanged","#shopEditForm")}function saveShop(n){var t=function(n){uploadShopList(n.id,null)};validateForm($("#"+n),()=>{var i=new FormData($("#"+n)[0]);postFormData(url="/ShopAction/Save",i=i,onSuccess=t,onError=null)},null)}$(function(){$(document).on(AppStartEvent.eventName,n=>{n.detail.appName&&n.detail.appName=="shopapp"&&Object.hasOwn(n.detail,"shopId")&&uploadShopList(n.detail.shopId,loadShop)})});